import math

def check_solution(a, b):
    try:
        LHS = (2**a) * (5**b) + 625
        N_float = math.sqrt(LHS)
        N_int = int(round(N_float))

        if N_int * N_int == LHS:
            return (a, b, N_int)
        return None
    except OverflowError:
        return None

solutions = []
# Search range for a and b
A_RANGE = range(-10, 11) # Allowing negative a for completeness, though 2^a is always positive
B_RANGE = range(-10, 11) # Allowing negative b

print("Searching for solutions (a, b, N) in range a=[-10, 10], b=[-10, 10]...")
for a in A_RANGE:
    for b in B_RANGE:
        result = check_solution(a, b)
        if result:
            solutions.append(result)

print(f"Found solutions: {solutions}")
print(f"Total solutions found in search range: {len(solutions)}")

